mapper.select:
SELECT dept_name AS deptName, -- 科室名称 NVL(SUM(patient_count), 0) AS patientCount, -- 患者人数 NVL(SUM(treatment_count), 0) AS treatmentCount, -- 治疗人次 NVL(SUM(treatment_amount), 0) AS treatmentAmount, -- 治疗金额 ROUND(NVL(SUM(treatment_amount), 0) / NULLIF(SUM(treatment_count), 0), 2) AS avgAmount -- 平均金额 FROM TR_TREAT_STAT_DTL t INNER JOIN TR_DEPT_DICT d ON t.dept_code = d.dept_code WHERE t.stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
GROUP BY d.dept_name ORDER BY treatmentCount DESC
